examples.template:
ScrollView {
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        ForEach(1...{{events.count}}, id: \.self) { number in
            Text("{{events.prefix|raw}}\(number){{events.suffix|raw}}")
                .monarchTextStyle(.body)
        }
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    .padding(theme.spacing.space3)
}
.scrollIndicators(.visible)
.frame(maxWidth: {{maxWidth}}, maxHeight: {{maxHeight}})
.mask(
    VStack(spacing: 0) {
        Color.black
        LinearGradient(colors: [.black, .clear], startPoint: .top, endPoint: .bottom).frame(height: 32)
    }
)
.overlay(RoundedRectangle(cornerRadius: theme.radius.lg).stroke(theme.colors.borderDefault))
.accessibilityLabel({{label}})

